#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j, row-major (j is the innermost / contiguous dimension)
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec);
	// A: i x k (M x M), row-major (k is the innermost / contiguous dimension)
	DEFINE_PROTO_STRUCT(a_layout, i_vec ^ k_vec);
	// B: i x j (M x N), row-major (j is the innermost / contiguous dimension)
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
//
// We compute (BLAS SYMM, left, lower)
//
//   C := beta * C + alpha * A_symm * B
//
// where A_symm is the symmetric extension of the stored lower–triangular A:
//   A_symm(i,k) = A[i,k] if k <= i, else A[k,i].
//
// Compared to the original kernel, this version:
//   * scales C by beta in a separate pass (same net effect),
//   * uses two temporary row buffers temp1[j] and temp2[j]
//       - temp1[j] = alpha * B[i,j]   (hoisted out of the k-loop)
//       - temp2[j] accumulates sum_{k<i} B[k,j] * A[i,k]
//   * accesses only the stored lower triangle of A (k < i, plus A[i,i]),
//   * keeps all j-loops unit-stride thanks to row-major layouts, and
//   * expresses all iteration over i, j, k via Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Problem dimensions
	const auto m = C | get_length<'i'>();
	const auto n = C | get_length<'j'>();

	// Per-row temporaries over dimension 'j':
	// temp1[j] = alpha * B[i, j] for current i
	// temp2[j] = sum_{k<i} B[k, j] * A[i, k] for current i
	//
	// These add only O(N) extra storage and are reused for each i.
	auto temp1 = bag(scalar<num_t>() ^ vector<'j'>(n));
	auto temp2 = bag(scalar<num_t>() ^ vector<'j'>(n));

	#pragma scop

	// 1) Pre-scale C by beta once:
	//    C := beta * C
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// 2) Symmetric matrix–matrix multiply using only the stored lower triangle of A.
	//
	// For each row i:
	//   - precompute temp1[j] = alpha * B[i, j] and zero temp2[j],
	//   - for each k < i, use A[i, k] once to:
	//       * update row k of C: C[k, j] += alpha * B[i, j] * A[i, k]
	//       * accumulate into temp2[j]:  temp2[j] += B[k, j] * A[i, k]
	//   - finally, for row i:
	//       C[i, j] += alpha * B[i, j] * A[i, i]
	//                 + alpha * sum_{k<i} B[k, j] * A[i, k]
	//
	// Across all i, this is algebraically identical to:
	//   C := beta*C + alpha*A_symm*B.
	traverser(A, B, C).template for_dims<'i'>([&](auto trav_i) {
		// Current row index i
		const auto state_i = trav_i.state();
		const auto i_idx   = get_index<'i'>(state_i);

		// Views of the i-th row in B and C (1D in 'j')
		auto B_row_i = B ^ fix<'i'>(i_idx);
		auto C_row_i = C ^ fix<'i'>(i_idx);

		// 2a) Precompute temp1[j] = alpha * B[i, j] and initialize temp2[j] = 0
		traverser(B_row_i, temp1, temp2).for_each([&](auto s_j) {
			const num_t bij = B_row_i[s_j];
			temp1[s_j] = alpha * bij; // hoist alpha*B[i, j] out of k-loop
			temp2[s_j] = num_t(0);   // reset accumulator for current row i
		});

		// 2b) Strictly lower-triangular part: 0 <= k < i
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			const auto s_ik = trav_ik.state();
			const auto k_idx = get_index<'k'>(s_ik);

			// Only use the stored lower triangle A[i, k] with k < i.
			// This also avoids ever reading the -999 sentinel values in the
			// upper triangle created in init_array.
			if (k_idx >= i_idx) return;

			const num_t a_ik = A[s_ik]; // A[i, k], with k < i

			// Views of the k-th row in C and B (1D in 'j')
			auto C_row_k = C ^ fix<'i'>(k_idx);
			auto B_row_k = B ^ fix<'i'>(k_idx);

			// Update row k of C and accumulate contributions to row i via temp2.
			traverser(temp1, temp2, C_row_k, B_row_k).for_each([&](auto s_j) {
				const num_t t1   = temp1[s_j];   // alpha * B[i, j]
				const num_t b_kj = B_row_k[s_j]; // B[k, j]
				num_t &c_kj      = C_row_k[s_j]; // C[k, j]

				// C[k, j] += alpha * B[i, j] * A[i, k]
				c_kj += t1 * a_ik;

				// temp2[j] += B[k, j] * A[i, k]
				temp2[s_j] += b_kj * a_ik;
			});
		});

		// 2c) Finish row i: diagonal and accumulated lower-triangular terms.
		//
		// At this point, for every j:
		//   temp2[j] = sum_{k=0..i-1} B[k, j] * A[i, k].
		//
		// We now add:
		//   alpha * B[i, j] * A[i, i]          (diagonal)
		//   + alpha * temp2[j]                 (lower triangle)
		// to C[i, j].  The symmetric contributions from A[k, i] for k > i
		// are added later when the outer loop reaches row k, exactly as in
		// the original kernel.
		const num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];

		traverser(C_row_i, temp1, temp2).for_each([&](auto s_j) {
			const num_t t1 = temp1[s_j]; // alpha * B[i, j]
			const num_t t2 = temp2[s_j]; // sum_{k<i} B[k, j] * A[i, k]

			C_row_i[s_j] += t1 * a_ii + alpha * t2;
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
