//
// Original kernel (schematically):
//   for i
//     for j
//       temp2 = 0
//       for k
//         if (k < i) {
//           C[k, j] += alpha * B[i, j] * A[i, k];
//           temp2   +=          B[k, j] * A[i, k];
//         }
//       C[i, j] = beta * C[i, j]
//                 + alpha * B[i, j] * A[i, i]
//                 + alpha * temp2;
//
// This matches BLAS SYMM (left, lower).
//
// Optimizations applied here:
//   1. Factor out beta scaling into a separate pass: C := beta * C.
