//   2. Use two temporary row buffers temp1[j], temp2[j] per row i:
//        temp1[j] = alpha * B[i, j]              (hoisted from k-loop)
//        temp2[j] = sum_{k<i} B[k, j] * A[i, k]  (accumulated over k)
//      This removes repeated loads and multiplications inside the k-loop
//      and keeps accumulators in registers.
//   3. Reorder loops so that j is innermost, which matches the row-major
//      layout of B and C (j is the fast dimension), improving locality
//      and vectorization opportunities.
//   4. Remove the "if (k < i)" branch from the inner loop by using a
//      Noarr slice over k: we iterate k only in [0, i) for each i.
//
// All loops are expressed using Noarr traversers and states.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Problem size in the column dimension (used for temporaries)
	auto n = C | get_length<'j'>();

	// Per-row temporaries:
	//   temp1[j] = alpha * B[i, j]
	//   temp2[j] = sum_{k<i} B[k, j] * A[i, k]
	//
	// These are length-N vectors in the 'j' dimension and are reused for each row i.
