	auto temp2 = noarr::bag(noarr::scalar<num_t>() ^ noarr::vector<'j'>(n));

	#pragma scop
	// 1) Pre-scale C by beta once:
	//    C := beta * C
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// 2) Symmetric matrix–matrix multiply:
	//    C := C + alpha * A_sym * B
	//    where A_sym uses only the stored lower triangle of A.
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has the current 'i' fixed; 'j' and 'k' remain free.
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ---------------------------------------------------------------------
		// 2.a) Initialize temp1[j] and temp2[j] for this row i.
		//
		//      temp1[j] = alpha * B[i, j]
		//      temp2[j] = 0
		// ---------------------------------------------------------------------
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			auto s_j = idx<'j'>(j_idx);

			// alpha * B[i, j], reused across all k for this (i, j)
			temp1[s_j] = alpha * B[state_ij];

			// accumulator for contributions destined for C[i, j]
			temp2[s_j] = (num_t)0;
		});

		// ---------------------------------------------------------------------
		// 2.b) Strictly lower-triangular part: k in [0, i).
		//
		// For each k < i:
		//   - C[k, j] receives alpha * A[i, k] * B[i, j]
		//   - temp2[j] accumulates A[i, k] * B[k, j]
		//
		// Using a sliced traverser over 'k' removes the inner "if (k < i)".
		// ---------------------------------------------------------------------
		auto trav_i_k = trav_i.order(noarr::slice<'k'>(0, i_idx));

		trav_i_k.template for_dims<'k'>([&](auto trav_ik) {
			auto state_ik = trav_ik.state();
			auto k_idx = get_index<'k'>(state_ik);

			// A[i, k] with k < i (only lower triangle is stored / used)
			num_t a_ik = A[state_ik];

			// For this (i, k), update:
			//   - the entire row k of C
			//   - temp2 for row i
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				auto state_ikj = trav_ikj.state();
				auto j_idx = get_index<'j'>(state_ikj);

				auto s_j  = idx<'j'>(j_idx);
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);

				// C[k, j] += alpha * B[i, j] * A[i, k]
				C[s_kj] += temp1[s_j] * a_ik;

				// temp2[j] += B[k, j] * A[i, k]
				temp2[s_j] += B[s_kj] * a_ik;
			});
		});

		// ---------------------------------------------------------------------
		// 2.c) Diagonal and accumulated lower-triangular contributions for row i.
		//
		// At this point, for each j:
		//   temp2[j] = sum_{k=0..i-1} B[k, j] * A[i, k]
		//
		// We now add to C[i, j]:
		//   alpha * B[i, j] * A[i, i] + alpha * temp2[j]
		// ---------------------------------------------------------------------
		num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			auto s_j = idx<'j'>(j_idx);

