		else
			A[state] = (num_t)-999;
	});
}

/*
 * Optimized symmetric matrix-matrix multiply kernel
 *
 * Original kernel (in this file before optimization) implements:
 *
 *   for i in [0, M)
 *     for j in [0, N)
 *       temp2 = 0
 *       for k in [0, M)
 *         if (k < i) {
 *           C[k,j] += alpha * B[i,j] * A[i,k];
 *           temp2  +=          B[k,j] * A[i,k];
 *         }
 *       C[i,j] = beta * C[i,j]
 *              + alpha * B[i,j] * A[i,i]
 *              + alpha * temp2;
 *
 * where A is lower-triangular (k <= i valid) and logically symmetric.
 *
 * This computes
 *   C := beta * C + alpha * A_sym * B,
 * where A_sym is the full symmetric matrix induced by the stored lower
 * triangle of A.
 *
 * The optimized kernel below keeps exactly the same mathematical result and
 * uses the same set of A-elements (only k <= i), but:
 *   - scales C by beta in a separate pass (one multiply per element),
 *   - hoists alpha * B[i,j] out of the inner loops,
 *   - uses two per-row temporary buffers temp1[j], temp2[j] (size N each),
 *   - reorders loops to make j the innermost dimension for good cache
 *     behavior and vectorization (B and C are row-major, j-contiguous),
 *   - avoids a k<i test inside the innermost j-loop (it is done once per k).
 */
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Length of the 'j' dimension (columns)
	const std::size_t n = C | get_length<'j'>();

	// Per-row temporaries:
	//   temp1[j] = alpha * B[i, j]  (for current i)
	//   temp2[j] = sum_{k<i} B[k, j] * A[i, k]  (for current i)
	// These are O(N) extra storage; negligible compared to A(M^2) and B,C(M*N).
	std::vector<num_t> temp1(n);
	std::vector<num_t> temp2(n);

	#pragma scop
	// 1) Scale the whole C by beta once.
	//    This is algebraically equivalent to the beta term inside the original
	//    kernel, because each C[i,j] is multiplied by beta exactly once and
	//    all subsequent updates are additive.
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// 2) Symmetric matrix-matrix multiply using only the stored lower triangle
	//    of A. For each row i:
	//      - temp1[j] = alpha * B[i,j]
	//      - temp2[j] accumulates contributions for C[i,j] from A[i,k], k < i
	//      - C[k,j] (k < i) is updated symmetrically using the same A[i,k]
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has dimension 'i' fixed; 'j' and 'k' (if present) remain free.

		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// 2.a Precompute temp1[j] = alpha * B[i,j] and reset temp2[j] = 0,
		//     for the current row i and all columns j.
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// trav_ij has 'i' and 'j' fixed; 'k' is still free.
			auto state_ij = trav_ij.state();
			const std::size_t j_idx = get_index<'j'>(state_ij);

			temp1[j_idx] = alpha * B[state_ij];
			temp2[j_idx] = (num_t)0;
		});

		// 2.b Process strictly lower-triangular elements A[i,k] with k < i.
		//     For each such k:
		//       - C[k,j] += alpha * B[i,j] * A[i,k]   (symmetric row update)
		//       - temp2[j] += B[k,j] * A[i,k]        (contribution to C[i,j])
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			auto state_ik = trav_ik.state();
			const std::size_t k_idx = get_index<'k'>(state_ik);

			// Only use the stored lower triangle: k < i.
			// For k >= i there is nothing to do (original kernel used: if (k < i)).
			if (k_idx >= i_idx)
				return; // skip this k without iterating j

			const num_t a_ik = A[state_ik]; // A[i, k], valid only for k <= i

			// Inner j-loop: update row k of C and accumulate into temp2 for row i.
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				auto state_ikj = trav_ikj.state();
				const std::size_t j_idx = get_index<'j'>(state_ikj);

				// State for C[k, j] and B[k, j]
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				// temp1[j_idx] == alpha * B[i, j_idx]

				// Symmetric update of row k:
				C[s_kj] += temp1[j_idx] * a_ik;      // == alpha * B[i,j] * A[i,k]

				// Contribution to row i accumulated in temp2:
				temp2[j_idx] += B[s_kj] * a_ik;      // sum_{k<i} B[k,j] * A[i,k]
			});
		});

		// 2.c Finalize row i: add diagonal A[i,i] term and the accumulated
		//     lower-triangular contributions stored in temp2[j].
		const num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			const std::size_t j_idx = get_index<'j'>(state_ij);

			// C[i,j] already contains beta * C0[i,j] from step 1.
			// Now add:
			//   alpha * B[i,j] * A[i,i]  via temp1[j] * a_ii
			//   alpha * sum_{k<i} B[k,j] * A[i,k]  via alpha * temp2[j]
			C[state_ij] += temp1[j_idx] * a_ii + alpha * temp2[j_idx];
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

