// -----------------------------------------------------------------------------
// Optimized computation kernel
//
// Original mathematical operation (BLAS SYMM, left, lower):
//   C := beta * C + alpha * A_sym * B
// where A_sym is the symmetric extension of the lower-triangular A:
//
//   A_sym[i, k] = A[i, k]  for k <= i
//   A_sym[i, k] = A[k, i]  for k > i
//
// The original kernel implements this using a triple nest over (i, j, k)
// with a conditional on k < i and scatter updates to C[k, j].
// That leads to poor locality in B and C along the k dimension
// (column-wise, i-varying accesses in row-major layout).
//
// The optimized kernel below follows the symm-03 model:
//
//   For each row i:
//     1) Scale row i of C by beta.
//     2) Initialize a temporary row buffer temp2[j] to 0.
//     3) For all k < i (strictly lower triangle):
//           aik = A[i, k]
//           For all j:
//             C[k, j] += alpha * B[i, j] * aik      // scatter to row k
//             temp2[j] += B[k, j] * aik             // accumulate for row i
//     4) Add diagonal and accumulated lower-triangular contributions:
//           aii = A[i, i]
//           For all j:
//             C[i, j] += alpha * (B[i, j] * aii + temp2[j])
//
// This algorithm:
//   * Uses only the stored lower triangle of A (k <= i).
//   * Produces the same result as the original kernel.
//   * Reorders loops so that all heavy inner loops run over j, which is the
//     contiguous dimension in our row-major B and C, greatly improving
//     spatial locality and SIMD vectorization opportunities.
//   * Uses a per-row temporary buffer temp2[j], adding only O(N) extra
//     storage, negligible compared to A (M^2) and B,C (M*N).
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Problem dimensions
	const std::size_t m = C | get_length<'i'>();
	const std::size_t n = C | get_length<'j'>();

	// Per-row temporary accumulator:
	//   temp2[j] = sum_{k < i} B[k, j] * A[i, k]
	std::vector<num_t> temp2(n);

	#pragma scop
	// Traverse all three bags together; dimensions are 'i', 'j', 'k'.
	// We drive the outermost loop explicitly over 'i' (rows).
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; 'j' and 'k' are still available.
		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// ---------------------------------------------------------------------
		// 1) Scale row i of C by beta and initialize temp2[j] = 0
		//
		// We iterate all columns j for this fixed i, touching each (i, j) once.
		// This preserves the original semantics where each C[i, j] is scaled
		// by beta exactly once, before any contributions to that element.
		// ---------------------------------------------------------------------
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state(); // contains 'i' and 'j'
			const std::size_t j_idx = get_index<'j'>(state_ij);

			C[state_ij] *= beta;
			temp2[j_idx] = num_t(0);
		});

		// ---------------------------------------------------------------------
		// 2) Strictly lower-triangular part: k in [0, i)
		//
		// For each k < i:
		//   aik = A[i, k]
		//   For all j:
		//     C[k, j] += alpha * B[i, j] * aik
		//     temp2[j] += B[k, j] * aik
		//
		// We use a noarr::slice on 'k' to restrict the traversal to [0, i)
		// and avoid an explicit conditional on (k < i) inside the loop.
		// The slice is applied only on the traverser (via .order), so that
		// the states we obtain still use the original indices.
		// ---------------------------------------------------------------------
		auto k_slice = noarr::slice<'k'>(std::size_t(0), i_idx);

		trav_i.order(k_slice).template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed, with 0 <= k < i_idx
			auto state_ik = trav_ik.state();
			const std::size_t k_idx = get_index<'k'>(state_ik);

			// A[i, k] is used for all columns j for this (i, k)
			const num_t aik = A[state_ik];

			// Inner loop over j (contiguous dimension in row-major B, C):
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				auto state_ikj = trav_ikj.state(); // contains 'i', 'k', 'j'
				const std::size_t j_idx = get_index<'j'>(state_ikj);

				// Build states for the various rows we need:
				//   - C[k, j] and B[k, j] use row index k
				//   - B[i, j] uses row index i
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				auto s_ij = idx<'i', 'j'>(i_idx, j_idx);

				// Update row k of C: C[k, j] += alpha * B[i, j] * A[i, k]
				C[s_kj] += alpha * B[s_ij] * aik;

				// Accumulate contribution to row i of C:
				//   temp2[j] += B[k, j] * A[i, k]
				temp2[j_idx] += B[s_kj] * aik;
			});
		});

		// ---------------------------------------------------------------------
		// 3) Diagonal and accumulated lower-triangular contributions for row i
		//
		// At this point, for the current i and every j:
		//   temp2[j] = sum_{k = 0..i-1} B[k, j] * A[i, k]
		//
		// The remaining row-i contribution is:
		//   alpha * (B[i, j] * A[i, i] + temp2[j])
		// which we now add to C[i, j].
		// ---------------------------------------------------------------------
		auto state_ii = idx<'i', 'k'>(i_idx, i_idx);
		const num_t aii = A[state_ii];

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			const std::size_t j_idx = get_index<'j'>(state_ij);

			C[state_ij] += alpha * (B[state_ij] * aii + temp2[j_idx]);
		});
	});
	#pragma endscop
